{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Labetalol, a basic secondary amine with a primary carboxamide, had absolute oral bioavailability of 28% (19-49%) in subjects, directly supporting F≥20% for the query's similar ionizable amine/amide scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "One labetalol record reported oral bioavailability of 4-17% (mean 9%) at a 200 mg dose, indicating variable first-pass metabolism; this is a contradictory data point but is outweighed by multiple absolute F measurements of 26-33%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C20"],
      "claim": "L-5-hydroxytryptophan, an indole-containing polar amino acid, achieved 49% absolute bioavailability, supporting that an indole/amine polar scaffold can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Pramipexole, a small basic amine, showed >90% oral bioavailability, indicating that strong basicity alone does not preclude high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "AZD0837, a basic amidine/amide drug, had absolute oral bioavailability of 22-52% in humans, supporting F≥20% for a polar basic amide-containing molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Isradipine had ~17% systemic availability in healthy volunteers, a low-F example, but its neutral dihydropyridine/ester structure is less transferable to the query's basic amine/amide scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of high-transfer experimental evidence from basic amine/amide and indole-containing drugs (labetalol ~28%, 5-HTP 49%, pramipexole >90%, AZD0837 22-52%) supports F≥20%, despite a low physicochemical prior and a few low-F outliers.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the exact query molecule.",
    "First-pass metabolism and transporter effects (e.g., P-gp) are not experimentally characterized for the query.",
    "The low logD/ionization prior suggests a permeability risk that is not directly measured in the available analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

